// Function to show custom install instructions specifically for iOS Safari users
function setupIosInstallPrompt() {
  const isIosDevice = /iphone|ipad|ipod/.test(window.navigator.userAgent.toLowerCase());
  const isInStandalone = window.navigator.standalone === true;

  if (isIosDevice && !isInStandalone) {
    // Show custom modal guiding the user
    const iosBanner = document.getElementById('ios-install-banner');
    if (iosBanner) {
      iosBanner.style.display = 'block';
      iosBanner.innerHTML = `
        <p>Install this AI App on your iPhone: tap <img src="share-icon.png" alt="Share"> and select <strong>Add to Home Screen</strong>.</p>
      `;
    }
  }
}

window.addEventListener('DOMContentLoaded', setupIosInstallPrompt);

