// Service Worker using Workbox v7
importScripts('https://storage.googleapis.com/workbox-cdn/releases/7.0.0/workbox-sw.js');

if (workbox) {
  console.log('Workbox is loaded 🎉');

  // Precaching assets generated by build
  workbox.precaching.precacheAndRoute([
    { url: '/index.html', revision: '383676' },
    { url: '/styles/main.css', revision: '123456' }
  ]);

  // Cache CSS and JavaScript files with Stale-While-Revalidate strategy
  workbox.routing.registerRoute(
    ({request}) => request.destination === 'script' || request.destination === 'style',
    new workbox.strategies.StaleWhileRevalidate({
      cacheName: 'static-resources',
    })
  );
} else {
  console.log('Workbox failed to load.');
}

// Client-side triggering background sync
async function postMessage(data) {
  try {
    const response = await fetch('/api/messages', {
      method: 'POST',
      body: JSON.stringify(data),
      headers: { 'Content-Type': 'application/json' }
    });
    if (!response.ok) throw new Error('Network response failed');
  } catch (error) {
    // If offline, queue the request and register sync
    const registration = await navigator.serviceWorker.ready;
    await saveToIndexedDB('outbox', data);
    await registration.sync.register('sync-outbox');
    console.log('Sync registered for background retry.');
  }
}

